import {state,post,uploadFile,refresh} from './api.js';
import {esc,icon,field,choices,formDialog,dialog,localNow,toUTC,toast,formatDate,formatTime} from './ui.js';

export function reportLocation(row){if(row.latitude==null)return `<p class="muted text-small">${esc(row.post_name||'Lokasi perangkat belum dicatat pada laporan lama.')}</p>`;return `<section class="detail-section"><h3>Lokasi pelaporan</h3><div class="location-result">${icon('location')}<div><strong>${Number(row.latitude).toFixed(6)}, ${Number(row.longitude).toFixed(6)}</strong><p>Akurasi ±${Math.round(row.location_accuracy)} m · ${formatDate(row.location_captured_at)} ${formatTime(row.location_captured_at)} WITA</p></div></div><p class="form-note">Koordinat perangkat saat pelaporan.</p></section>`;}
export function reportPhotos(files){return files?.length?`<div class="evidence-grid">${files.map(f=>['image/jpeg','image/png'].includes(f.mime_type)?`<figure><button class="evidence-image" data-action="report-photo" data-id="${f.id}" aria-label="Perbesar foto bukti"><img src="/api/files/${f.id}?inline=1" alt="${esc(f.caption||'Foto bukti laporan')}" loading="lazy"></button><figcaption>${f.captured_at?`${formatDate(f.captured_at)} ${formatTime(f.captured_at)} WITA`:'Lampiran laporan lama'}</figcaption></figure>`:`<a class="file-link" href="/api/files/${f.id}" download>${icon('download')}${esc(f.original_name)}</a>`).join('')}</div>`:'<p class="muted text-small">Belum ada foto pada laporan lama.</p>';}
export function showReportPhoto(id){dialog('Foto bukti',`<img class="image-expanded" src="/api/files/${encodeURIComponent(id)}?inline=1" alt="Foto bukti laporan">`,{wide:true});}
export function openFieldReport(incident=false,source=null){
  if(!window.isSecureContext){dialog('Kamera dan lokasi memerlukan HTTPS','<p class="detail-prose">Buka aplikasi melalui alamat HTTPS agar kamera dan lokasi dapat digunakan dari perangkat ini. Untuk pengembangan pada komputer server, gunakan localhost atau 127.0.0.1.</p>');return;}
  if(!state.me.user.employee_id){dialog('Profil petugas belum terhubung','<p class="detail-prose">Hubungi Admin/SDM untuk menghubungkan akun Anda dengan profil pegawai sebelum membuat laporan.</p>');return;}
  let location=null,stream=null,photos=[],closed=false;
  const key=crypto.randomUUID(),urls=[];
  const fields=`<section class="full field-report-identity"><span class="stat-icon">${icon('shield')}</span><div><span class="detail-label">${incident?'Pelapor':'Petugas'}</span><strong>${esc(state.me.name)}</strong><small>Diisi otomatis dari akun Anda</small></div></section><section class="full capture-location"><div class="section-title"><h3>Lokasi perangkat <span class="required-label">Wajib</span></h3><button class="button outlined" type="button" data-capture-location>${icon('location')}Ambil lokasi</button></div><p data-location-status role="status">Ambil lokasi perangkat untuk melengkapi laporan.</p><p class="form-note">Izinkan akses lokasi saat diminta browser.</p></section>`+field(`${incident?'Waktu kejadian':'Waktu kegiatan'} (WITA)`,'occurred_at','datetime-local',localNow())+(incident?field('Kategori kejadian','incident_type','text','','maxlength="200" placeholder="Contoh: Barang tertinggal"')+field('Kronologi','chronology','textarea',source?.activity_notes||source?.findings||'','maxlength="20000" placeholder="Contoh: Pada pukul 10.00 WITA ditemukan tas tanpa pemilik di area parkir saat pemeriksaan area."'):field('Jenis kegiatan','activity_type','select',choices(['JAGA','PATROLI','LAINNYA'],'PATROLI')))+(!incident?field('Uraian kegiatan','activity_notes','textarea','','maxlength="10000" placeholder="Contoh: Melakukan patroli di area parkir. Memeriksa penerangan dan akses keluar masuk. Ditemukan satu lampu padam dan sudah dilaporkan kepada koordinator."'):'')+`<section class="full camera-section"><div class="section-title"><h3>Foto bukti <span class="required-label">Wajib</span></h3><button class="button outlined" type="button" data-open-camera>${icon('camera')}Buka kamera</button></div><p class="form-note">Ambil 1–5 foto melalui kamera aplikasi. Periksa hasilnya sebelum mengirim.</p><div class="camera-view" hidden><video autoplay muted playsinline aria-label="Pratinjau kamera"></video><div class="actions"><button type="button" class="button primary" data-take-photo disabled>${icon('camera')}Ambil foto</button><button type="button" class="button outlined" data-stop-camera>Tutup kamera</button></div></div><p data-camera-status role="status"></p><div class="evidence-grid" data-capture-photos></div></section>`;
  const modal=formDialog(incident?'Laporkan kejadian':'Catat kegiatan lapangan',fields,async(b)=>{
    if(!location)throw new Error('Lokasi perangkat wajib berhasil didapatkan.');
    if(!photos.length)throw new Error('Ambil minimal satu foto melalui kamera aplikasi.');
    const submittedPhotos=[...photos],submittedLocation={...location};
    for(const photo of submittedPhotos)if(!photo.file_id)photo.file_id=(await uploadFile(photo.file)).id;
    const payload={...b,occurred_at:toUTC(b.occurred_at),location:submittedLocation,idempotency_key:key,photos:submittedPhotos.map(p=>({file_id:p.file_id,captured_at:p.captured_at,source:'CAMERA'}))};
    if(incident)payload.source_logbook_entry_id=source?.id||null;
    await post(incident?'incidents':'logbook',payload);toast(incident?'Laporan kejadian berhasil dikirim.':'Kegiatan lapangan berhasil dicatat.');refresh();
  },{submit:'Kirim laporan',note:'Lokasi dan foto kamera wajib tersedia. Waktu kegiatan/kejadian dan waktu penerimaan laporan dicatat terpisah.'});
  const submit=modal.querySelector('[type=submit]'),locationStatus=modal.querySelector('[data-location-status]'),cameraStatus=modal.querySelector('[data-camera-status]'),video=modal.querySelector('video'),snap=modal.querySelector('[data-take-photo]');
  const sync=()=>{submit.disabled=!location||!photos.length;};
  const stopCamera=()=>{stream?.getTracks().forEach(track=>track.stop());stream=null;video.srcObject=null;modal.querySelector('.camera-view').hidden=true;snap.disabled=true;};
  function renderPhotos(){modal.querySelector('[data-capture-photos]').innerHTML=photos.map((p,i)=>`<figure><img src="${p.preview}" alt="Foto bukti ${i+1}"><figcaption>${formatTime(p.captured_at)} WITA<button type="button" class="icon-button" data-remove-photo="${i}" aria-label="Hapus foto ${i+1}">${icon('trash')}</button></figcaption></figure>`).join('');sync();}
  modal.querySelector('[data-capture-location]').addEventListener('click',()=>{location=null;sync();if(!window.isSecureContext||!navigator.geolocation){locationStatus.textContent='Akses lokasi memerlukan HTTPS atau localhost dan browser yang mendukung lokasi.';return;}const control=modal.querySelector('[data-capture-location]');control.disabled=true;locationStatus.textContent='Mengambil lokasi perangkat…';navigator.geolocation.getCurrentPosition(result=>{if(closed)return;location={latitude:result.coords.latitude,longitude:result.coords.longitude,accuracy:result.coords.accuracy,captured_at:new Date(result.timestamp).toISOString()};locationStatus.textContent=`Lokasi berhasil: ${location.latitude.toFixed(6)}, ${location.longitude.toFixed(6)} · akurasi ±${Math.round(location.accuracy)} m`;control.textContent='Ambil lokasi ulang';control.disabled=false;sync();},error=>{if(closed)return;locationStatus.textContent=error.code===1?'Izin lokasi ditolak. Izinkan lokasi melalui pengaturan situs browser, lalu coba lagi.':error.code===3?'Pengambilan lokasi melewati batas waktu. Coba lagi di area dengan sinyal lebih baik.':'Lokasi belum tersedia. Aktifkan layanan lokasi perangkat lalu coba lagi.';control.disabled=false;},{enableHighAccuracy:true,maximumAge:0,timeout:20000});});
  modal.querySelector('[data-open-camera]').addEventListener('click',async()=>{cameraStatus.textContent='';if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){cameraStatus.textContent='Kamera memerlukan HTTPS atau localhost dan browser yang mendukung kamera.';return;}const control=modal.querySelector('[data-open-camera]');control.disabled=true;try{stopCamera();const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1600},height:{ideal:1200}},audio:false});if(closed){media.getTracks().forEach(track=>track.stop());return;}stream=media;video.srcObject=media;modal.querySelector('.camera-view').hidden=false;await video.play();snap.disabled=false;}catch(error){stopCamera();cameraStatus.textContent=error.name==='NotAllowedError'?'Izin kamera ditolak. Izinkan kamera melalui pengaturan situs browser.':'Kamera belum bisa digunakan. Pastikan tersedia dan tidak sedang dipakai aplikasi lain.';}finally{control.disabled=false;}});
  snap.addEventListener('click',async()=>{if(photos.length>=5){cameraStatus.textContent='Maksimal lima foto. Hapus satu foto untuk mengambil ulang.';return;}if(!stream||!video.videoWidth){cameraStatus.textContent='Tunggu sampai pratinjau kamera terlihat.';return;}snap.disabled=true;try{const canvas=document.createElement('canvas'),scale=Math.min(1,1600/video.videoWidth,1600/video.videoHeight);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const captured_at=new Date().toISOString(),blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw new Error('Foto gagal diambil. Coba lagi.');if(closed)return;const file=new File([blob],`bukti-${Date.now()}.jpg`,{type:'image/jpeg'}),preview=URL.createObjectURL(blob);urls.push(preview);photos.push({file,preview,captured_at});cameraStatus.textContent='Foto berhasil diambil. Anda dapat menambah foto atau menutup kamera.';renderPhotos();}catch(error){cameraStatus.textContent=error.message;}finally{snap.disabled=!stream;}});
  modal.querySelector('[data-stop-camera]').addEventListener('click',stopCamera);
  modal.addEventListener('click',event=>{const control=event.target.closest('[data-remove-photo]');if(control){photos.splice(Number(control.dataset.removePhoto),1);renderPhotos();}});
  const stopOnNavigation=()=>modal.close();window.addEventListener('hashchange',stopOnNavigation);
  modal.addEventListener('close',()=>{closed=true;stopCamera();urls.forEach(url=>URL.revokeObjectURL(url));window.removeEventListener('hashchange',stopOnNavigation);},{once:true});sync();
}
